WITH RECURSIVE l(x)AS(VALUES(0) UNION ALL SELECT x+1 FROM l WHERE x<3),o(y)AS(VALUES(0) UNION ALL SELECT y+1 FROM o WHERE y<3),p(x,y)AS(VALUES(-1,0) UNION ALL SELECT x,y FROM l,o) SELECT 0,p.y,p.x,r.rowid,r.a,r.b FROM p LEFT JOIN result r ON p.x<0 OR r.rowid>p.y AND r.rowid<=p.y+p.x UNION ALL SELECT 1,p.y,p.x,s.rowid,s.d,s.e FROM p LEFT JOIN result_flip s ON p.x<0 OR s.rowid>p.y AND s.rowid<=p.y+p.x ORDER BY 1,2,3,4